[{"order":1,"type":"heading","text":"Modern CSS: Scroll-driven Animations and View Transitions API"},{"order":2,"type":"paragraph","text":"Modern CSS has evolved to handle complex UI behaviors natively without relying on heavy JavaScript event listeners. Two powerful features—Scroll-driven Animations and the View Transitions API—allow developers to create high-performance scroll interactions and seamless page transitions directly in the style sheet."},{"order":3,"type":"subheading","text":"Understanding Scroll-driven Animations"},{"order":4,"type":"paragraph","text":"Scroll-driven animations link the progress of a CSS animation keyframe to the scroll position of a scroll container or the visibility of an element within a viewport, rather than tying it to wall-clock time."},{"order":5,"type":"code","text":"/* Scroll Progress Indicator Bar */
@keyframes grow-progress {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

.progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 8px;
  background-color: #007acc;
  transform-origin: left;
  animation: grow-progress auto linear;
  animation-timeline: scroll(root);
}

/* Element View-based Fade-in */
@keyframes fade-in {
  from { opacity: 0; transform: translateY(50px); }
  to { opacity: 1; transform: translateY(0); }
}

.card {
  animation: fade-in auto linear;
  animation-timeline: view();
  animation-range: entry 10% cover 30%;
}"},{"order":6,"type":"subheading","text":"Key Concepts of Scroll Timelines"},{"order":7,"type":"bullet_point","text":"'animation-timeline': Specifies the timeline used to drive the animation. Accepts functions like 'scroll()' or 'view()'."},{"order":8,"type":"bullet_point","text":"'scroll()': Defines an anonymous scroll timeline tied to a scroll container (e.g., 'root' or 'nearest')."},{"order":9,"type":"bullet_point","text":"'view()': Defines an anonymous view progress timeline based on the element's position relative to its scroll container."},{"order":10,"type":"bullet_point","text":"'animation-range': Sets the start and end offsets for view-driven animations using keywords like 'entry', 'exit', or 'cover'."},{"order":11,"type":"subheading","text":"Implementing the View Transitions API"},{"order":12,"type":"paragraph","text":"The View Transitions API enables smooth visual changes between different DOM states or pages. It captures snapshots of old and new elements, animating the transition smoothly off the main thread."},{"order":13,"type":"code","text":"/* JavaScript Trigger */
function updateDOM() {
  document.getElementById("content").textContent = "New View Content";
}

function performTransition() {
  if (!document.startViewTransition) {
    updateDOM();
    return;
  }
  document.startViewTransition(() => updateDOM());
}

/* Custom View Transition Styling in CSS */
::view-transition-old(root) {
  animation: 300ms ease-out fade-out;
}

::view-transition-new(root) {
  animation: 300ms ease-in fade-in;
}

.hero-image {
  view-transition-name: hero-card;
}"},{"order":14,"type":"subheading","text":"Best Practices & Progressive Enhancement"},{"order":15,"type":"bullet_point","text":"Use feature queries with '@supports (animation-timeline: scroll())' to ensure fallback behaviors for unsupported browsers."},{"order":16,"type":"bullet_point","text":"Respect user accessibility choices by wrapping animations inside 'prefers-reduced-motion' media queries."},{"order":17,"type":"bullet_point","text":"Assign distinct 'view-transition-name' properties to persistent UI elements (like headers or hero images) to enable morphing animations across states."}]
